package reauthruntime

import (
	"archive/zip"
	"bytes"
	"crypto/sha256"
	_ "embed"
	"encoding/hex"
	"fmt"
	"io"
	"io/fs"
	"os"
	"path/filepath"
	"slices"
)

const codexOverlayVersion = "2.19.1"

// codexOverlay is generated by python tools/reauth-runtime/sync_codex_overlay.py.
//
//go:embed codex_overlay.zip
var codexOverlay []byte

const codexOverlayBootstrap = `from pathlib import Path
import runpy
import sys

base = Path(__file__).resolve().parent.parent
sys.path.append(str(base))
runpy.run_path(str(base / "worker.py"), run_name="__main__")
`

var codexOverlayNames = []string{
	"openai_codex_oauth_adapter.py",
	"openai_codex_diagnostics.mjs",
	"openai_codex_password_flow.mjs",
}

func codexOverlayWorker(base, version string) (string, error) {
	if version != codexOverlayVersion {
		return filepath.Join(base, "worker.py"), nil
	}
	files, err := readCodexOverlay()
	if err != nil {
		return "", err
	}
	hash := sha256.New()
	_, _ = hash.Write(codexOverlay)
	_, _ = io.WriteString(hash, codexOverlayBootstrap)
	dir := filepath.Join(base, "codeq-codex-"+hex.EncodeToString(hash.Sum(nil)))
	worker := filepath.Join(dir, "worker.py")
	if err := checkCodexOverlay(dir, files); err == nil {
		return worker, nil
	} else if !os.IsNotExist(err) {
		return "", err
	}

	staging, err := os.MkdirTemp(base, ".codeq-codex-")
	if err != nil {
		return "", err
	}
	defer func() { _ = os.RemoveAll(staging) }()
	for name, data := range files {
		if err := os.WriteFile(filepath.Join(staging, name), data, 0600); err != nil {
			return "", err
		}
	}
	if err := os.Rename(staging, dir); err != nil && checkCodexOverlay(dir, files) != nil {
		return "", err
	}
	return worker, nil
}

func readCodexOverlay() (map[string][]byte, error) {
	archive, err := zip.NewReader(bytes.NewReader(codexOverlay), int64(len(codexOverlay)))
	if err != nil {
		return nil, err
	}
	if len(archive.File) != len(codexOverlayNames) {
		return nil, fmt.Errorf("invalid Codex overlay file count")
	}
	files := map[string][]byte{"worker.py": []byte(codexOverlayBootstrap)}
	for _, entry := range archive.File {
		if _, found := files[entry.Name]; found || !slices.Contains(codexOverlayNames, entry.Name) || !entry.Mode().IsRegular() {
			return nil, fmt.Errorf("invalid Codex overlay entry %q", entry.Name)
		}
		data, err := fs.ReadFile(archive, entry.Name)
		if err != nil {
			return nil, err
		}
		files[entry.Name] = data
	}
	return files, nil
}

func checkCodexOverlay(dir string, files map[string][]byte) error {
	info, err := os.Lstat(dir)
	if err != nil {
		return err
	}
	if !info.IsDir() {
		return fmt.Errorf("invalid Codex overlay directory")
	}
	for name, expected := range files {
		path := filepath.Join(dir, name)
		info, err := os.Lstat(path)
		if err != nil || !info.Mode().IsRegular() || info.Size() != int64(len(expected)) {
			return fmt.Errorf("invalid Codex overlay file %q", name)
		}
		actual, err := os.ReadFile(path)
		if err != nil || !bytes.Equal(actual, expected) {
			return fmt.Errorf("invalid Codex overlay contents for %q", name)
		}
	}
	return nil
}
